const SILVER = '#aba7a8';

export class Discovery23UniformPack
  extends BaseTngEraUniformPack
  implements IUniformPack
{
  constructor() {
    super(UniformEra.Discovery23);
  }

  getUniformSwatches() {
    return [
      new Swatch(
        BodyType.AverageMale,
        'Average Male',
        (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              token.variant,
              BodyType.AverageMale,
            ),
            BodyType.AverageMale,
            token,
          ),
        'BodyType.averageMale',
      ),
      new Swatch(
        BodyType.AverageFemale,
        'Average Female',
        (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              token.variant,
              BodyType.AverageFemale,
            ),
            BodyType.AverageFemale,
            token,
          ),
        'BodyType.averageFemale',
      ),
    ];
  }

  getUniformVariantSwatches(token: TokenModel) {
    return [];
  }

  getUniformAndVariantBody(token: TokenModel) {
    const base = this.getUniformAndVariantByBodyType(
      token,
      token.variant,
      token.bodyType,
    );

    let insignia = '';
    if (token.bodyType === BodyType.AverageFemale) {
      if (
        DivisionColors.getDivision(this.era, token.divisionColor) === 'Medical'
      ) {
        insignia =
          Discovery23CenturyUniform.badgeDivisionIndicator.female.medical;
      } else if (
        DivisionColors.getDivision(this.era, token.divisionColor) === 'Command'
      ) {
        insignia =
          Discovery23CenturyUniform.badgeDivisionIndicator.female.command;
      } else if (
        DivisionColors.getDivision(this.era, token.divisionColor) ===
        'Operations'
      ) {
        insignia =
          Discovery23CenturyUniform.badgeDivisionIndicator.female.operations;
      } else if (
        DivisionColors.getDivision(this.era, token.divisionColor) === 'Science'
      ) {
        insignia =
          Discovery23CenturyUniform.badgeDivisionIndicator.female.science;
      }
    } else {
      if (
        DivisionColors.getDivision(this.era, token.divisionColor) === 'Medical'
      ) {
        insignia =
          Discovery23CenturyUniform.badgeDivisionIndicator.male.medical;
      } else if (
        DivisionColors.getDivision(this.era, token.divisionColor) === 'Command'
      ) {
        insignia =
          Discovery23CenturyUniform.badgeDivisionIndicator.male.command;
      } else if (
        DivisionColors.getDivision(this.era, token.divisionColor) ===
        'Operations'
      ) {
        insignia =
          Discovery23CenturyUniform.badgeDivisionIndicator.male.operations;
      } else if (
        DivisionColors.getDivision(this.era, token.divisionColor) === 'Science'
      ) {
        insignia =
          Discovery23CenturyUniform.badgeDivisionIndicator.male.science;
      }
    }
    return base + insignia;
  }

  getUniformAndVariantByBodyType(
    token: TokenModel,
    variant: UniformVariantType,
    bodyType: BodyType,
  ) {
    let base = '';
    let divisionColour = token.divisionColor;
    if (
      DivisionColors.getDivision(this.era, token.divisionColor) === 'Medical'
    ) {
      divisionColour = SILVER;
    }
    if (bodyType === BodyType.AverageMale) {
      base = Discovery23CenturyUniform.maleBody
        .replace(DefaultRed, divisionColour)
        .replace(SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX, token.skinColor);
    } else {
      base = Discovery23CenturyUniform.femaleBody
        .replace(DefaultRed, divisionColour)
        .replace(SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX, token.skinColor);
    }

    if (token.rankIndicator === Rank.Captain) {
      base = base.replace('#12284f', divisionColour);
    }
    if (
      DivisionColors.getDivision(this.era, token.divisionColor) === 'Medical'
    ) {
      base = base.replace('#1b3f7e', token.divisionColor);
      base = base.replace(
        '#12284e',
        SimpleColor.from(token.divisionColor)
          .blend(SimpleColor.from(SILVER), 0.25)
          .asHex(),
      );
      base = base.replace(
        '#12284f',
        SimpleColor.from(token.divisionColor)
          .blend(SimpleColor.from(SILVER), 0.25)
          .asHex(),
      );
      base = base.replace(
        '#122850',
        SimpleColor.from(token.divisionColor)
          .blend(SimpleColor.from(SILVER), 0.25)
          .asHex(),
      );
    }

    return (
      this.getNeck(
        bodyType,
        token.skinColor,
        token.species,
        UniformEra.DominionWar,
      ) + base
    );
  }

  getRankIndicator(token: TokenModel) {
    return '';
  }

  getBorderLogo(token: TokenModel): string {
    let base = borderInsignia.base;

    const division = DivisionColors.getDivision(this.era, token.divisionColor);
    if (division === 'Medical') {
      base = base.replace(DefaultRed, SILVER);
    } else {
      base = base.replace(DefaultRed, token.divisionColor);
    }

    if (division === 'Medical') {
      base += borderInsignia.medical;
    } else if (division === 'Science') {
      base += borderInsignia.science;
    } else if (division === 'Operations') {
      base += borderInsignia.operations;
    } else if (division === 'Command') {
      base += borderInsignia.command;
    }

    return base;
  }

  getBorderColor(token: TokenModel): string {
    const division = DivisionColors.getDivision(this.era, token.divisionColor);
    if (division === 'Medical') {
      return token.divisionColor;
    } else {
      return '#1e4582';
    }
  }

  getRankBorderIndicator(token: TokenModel): string {
    let divisionColour = token.divisionColor;

    const division = DivisionColors.getDivision(this.era, token.divisionColor);
    if (division === 'Medical') {
      divisionColour = '#aba7a8';
    }
    return (
      rankIndicators.border[Rank[token.rankIndicator]]?.replace(
        DefaultRed,
        divisionColour,
      ) ?? ''
    );
  }
}
